package com.aliucord.plugins.translate

import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.TextView
import androidx.cardview.widget.CardView
import com.aliucord.Utils
import com.aliucord.api.SettingsAPI
import com.aliucord.fragments.SettingsPage
import com.aliucord.plugins.translate.utils.getStrings
import com.discord.utilities.color.ColorCompat
import com.google.android.material.switchmaterial.SwitchMaterial
import com.google.android.material.textfield.TextInputEditText
import com.google.android.material.textfield.TextInputLayout
import com.lytefast.flexinput.R

class PluginSettings(private val settings: SettingsAPI) : SettingsPage() {

    override fun onViewBound(view: View?) {
        super.onViewBound(view)
        val ctx = requireContext()
        val strings = ctx.getStrings()
        val textColor = ColorCompat.getThemedColor(ctx, R.b.colorOnPrimary)
        val bgColor = ColorCompat.getThemedColor(ctx, R.b.colorSurface)

        setActionBarTitle(strings.settingsTitle)

        // ── Backend selector ──────────────────────────────────────
        addView(sectionLabel(strings.settingsBackendLabel, textColor))

        val backendGoogle = switchRow(strings.settingsBackendGoogle, textColor).apply {
            isChecked = settings.getString(SETTINGS_KEY_BACKEND, "google") == "google"
            setOnCheckedChangeListener { _, checked ->
                settings.setString(SETTINGS_KEY_BACKEND, if (checked) "google" else "llm")
                refreshUI()
            }
        }
        addView(backendGoogle)

        // ── LLM settings (shown only when backend = llm) ─────────
        val llmSection = LinearLayout(ctx).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(0, 20, 0, 20)
        }

        llmSection.addView(settingsInput(strings.settingsLLMBaseUrl, SETTINGS_KEY_LLM_BASE_URL, textColor, bgColor))
        llmSection.addView(settingsInput(strings.settingsLLMApiKey, SETTINGS_KEY_LLM_API_KEY, textColor, bgColor, isPassword = true))
        llmSection.addView(settingsInput(strings.settingsLLMModel, SETTINGS_KEY_LLM_MODEL, textColor, bgColor))

        val isLLM = settings.getString(SETTINGS_KEY_BACKEND, "google") == "llm"
        llmSection.visibility = if (isLLM) View.VISIBLE else View.GONE
        addView(llmSection)

        backendGoogle.setOnCheckedChangeListener { _, checked ->
            settings.setString(SETTINGS_KEY_BACKEND, if (checked) "google" else "llm")
            llmSection.visibility = if (checked) View.GONE else View.VISIBLE
        }

        // ── Default language ──────────────────────────────────────
        addView(sectionLabel(strings.settingsDefaultLanguage, textColor))

        val currentLang = languageCodes.entries.firstOrNull { it.value == settings.getString(SETTINGS_KEY_DEFAULT_LANG, DEFAULT_TARGET_LANG) }?.key
            ?: settings.getString(SETTINGS_KEY_DEFAULT_LANG, DEFAULT_TARGET_LANG)
        addView(cardRow("Default: $currentLang", textColor, bgColor))

        addView(sectionLabel(strings.settingsSupportedLanguages, textColor))

        languageCodes.forEach { (name, code) ->
            addView(textRow(name, textColor) {
                settings.setString(SETTINGS_KEY_DEFAULT_LANG, code)
                Utils.showToast(strings.settingsLanguageSaved)
                close()
            })
            addView(divider(bgColor))
        }

        // ── Text cleaning toggles ────────────────────────────────
        addView(sectionLabel("Text cleaning", textColor))

        addView(switchRow(strings.settingsCleanHtml, textColor).apply {
            isChecked = settings.getBool(SETTINGS_KEY_CLEAN_HTML, true)
            setOnCheckedChangeListener { _, v -> settings.setBool(SETTINGS_KEY_CLEAN_HTML, v) }
        })
        addView(switchRow(strings.settingsCleanUrl, textColor).apply {
            isChecked = settings.getBool(SETTINGS_KEY_CLEAN_URL, true)
            setOnCheckedChangeListener { _, v -> settings.setBool(SETTINGS_KEY_CLEAN_URL, v) }
        })
        addView(switchRow(strings.settingsCleanEmoji, textColor).apply {
            isChecked = settings.getBool(SETTINGS_KEY_CLEAN_EMOJI, true)
            setOnCheckedChangeListener { _, v -> settings.setBool(SETTINGS_KEY_CLEAN_EMOJI, v) }
        })
    }

    private fun refreshUI() { /* UI refreshes via the listener callbacks above */ }

    // ── Helper views ─────────────────────────────────────────────

    private fun sectionLabel(text: String, textColor: Int): TextView =
        TextView(requireContext()).apply {
            this.text = text
            setPadding(0, 30, 0, 10)
            setTextColor(textColor)
            textSize = 14f
        }

    private fun switchRow(label: String, textColor: Int): SwitchMaterial =
        SwitchMaterial(requireContext()).apply {
            text = label
            setTextColor(textColor)
            setPadding(0, 12, 0, 12)
        }

    private fun cardRow(text: String, textColor: Int, bgColor: Int): CardView =
        CardView(requireContext()).apply {
            layoutParams = ViewGroup.LayoutParams(MATCH_PARENT, WRAP_CONTENT)
            setPadding(40, 40, 40, 40)
            setContentPadding(20, 20, 20, 20)
            setCardBackgroundColor(bgColor)
            radius = 20f
            addView(TextView(context).apply {
                this.text = text
                setTextColor(textColor)
                textAlignment = TEXT_ALIGNMENT_CENTER
            })
        }

    private fun settingsInput(
        hint: String,
        key: String,
        textColor: Int,
        bgColor: Int,
        isPassword: Boolean = false
    ): TextInputLayout =
        TextInputLayout(requireContext()).apply {
            layoutParams = ViewGroup.LayoutParams(MATCH_PARENT, WRAP_CONTENT)
            setPadding(0, 12, 0, 12)
            this.hint = hint
            addView(TextInputEditText(context).apply {
                setText(settings.getString(key, ""))
                setTextColor(textColor)
                if (isPassword) inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
                setOnFocusChangeListener { _, hasFocus ->
                    if (!hasFocus) {
                        settings.setString(key, text.toString())
                    }
                }
            })
        }

    private fun textRow(text: String, textColor: Int, onClick: () -> Unit): TextView =
        TextView(requireContext()).apply {
            this.text = text
            setPadding(0, 15, 0, 15)
            setTextColor(textColor)
            setOnClickListener { onClick() }
        }

    private fun divider(bgColor: Int): View =
        View(requireContext()).apply {
            setPadding(0, 6, 0, 6)
            layoutParams = ViewGroup.LayoutParams(MATCH_PARENT, 2)
            setBackgroundColor(bgColor)
        }
}

package com.aliucord.plugins.translate

import com.aliucord.api.SettingsAPI

object TextCleaner {

    private val HTML_TAG_REGEX  = Regex("<[^>]*>")
    private val URL_REGEX       = Regex("https?://\\S+")
    private val EMOJI_REGEX     = Regex("[\\p{So}\\p{Sk}\\p{Sm}\\p{Sc}]+")

    fun clean(text: String, settings: SettingsAPI): String {
        var result = text

        if (settings.getBool(SETTINGS_KEY_CLEAN_HTML, true)) {
            result = result.replace(HTML_TAG_REGEX, "")
        }
        if (settings.getBool(SETTINGS_KEY_CLEAN_URL, true)) {
            result = result.replace(URL_REGEX, "")
        }
        if (settings.getBool(SETTINGS_KEY_CLEAN_EMOJI, true)) {
            result = result.replace(EMOJI_REGEX, "")
        }

        return result.trim()
    }
}

package com.aliucord.plugins.translate

import android.content.Context
import android.graphics.drawable.Drawable
import android.os.Bundle
import android.text.Spanned
import android.text.style.RelativeSizeSpan
import android.view.View
import android.widget.LinearLayout
import android.widget.TextView
import androidx.core.content.ContextCompat
import androidx.core.widget.NestedScrollView
import com.aliucord.Utils
import com.aliucord.annotations.AliucordPlugin
import com.aliucord.api.CommandsAPI
import com.aliucord.entities.Plugin
import com.aliucord.patcher.Hook
import com.aliucord.plugins.translate.auto.AutoTranslateManager
import com.aliucord.plugins.translate.auto.LanguageDetector
import com.aliucord.plugins.translate.utils.forceRerenderMessage
import com.aliucord.plugins.translate.utils.getStrings
import com.discord.api.commands.ApplicationCommandType
import com.discord.databinding.WidgetChatListActionsBinding
import com.discord.utilities.textprocessing.node.EditedMessageNode
import com.discord.utilities.view.text.SimpleDraweeSpanTextView
import com.discord.widgets.chat.list.WidgetChatList
import com.discord.widgets.chat.list.actions.WidgetChatListActions
import com.discord.widgets.chat.list.adapter.WidgetChatListAdapterItemMessage
import com.discord.widgets.chat.list.entries.MessageEntry
import com.facebook.drawee.span.DraweeSpanStringBuilder
import com.lytefast.flexinput.R
import java.lang.reflect.Field

@AliucordPlugin
class Translate : Plugin() {
    private var pluginIcon: Drawable? = null
    private lateinit var controller: TranslateController
    private lateinit var autoManager: AutoTranslateManager
    private lateinit var strings: com.aliucord.plugins.translate.strings.IStrings
    private var chatList: WidgetChatList? = null

    init {
        settingsTab = SettingsTab(PluginSettings::class.java).withArgs(settings)
    }

    override fun load(ctx: Context) {
        pluginIcon = ContextCompat.getDrawable(ctx, R.e.ic_locale_24dp)
        strings = ctx.getStrings()
        controller = TranslateController(settings)
        autoManager = AutoTranslateManager(settings)
    }

    override fun start(context: Context) {
        patchChatList()
        patchProcessMessageText()
        patchMessageContextMenu()
        registerTranslateCommand()
    }

    override fun stop(context: Context?) = patcher.unpatchAll()

    // ── Patches ────────────────────────────────────────────────────

    private fun patchChatList() {
        patcher.patch(WidgetChatList::class.java.getDeclaredConstructor(), Hook {
            val list = it.thisObject as WidgetChatList
            chatList = list
            controller.attachChatList(list)
        })

        // 拦截新消息到达，触发自动翻译
        patcher.patch(
            WidgetChatList::class.java,
            "onNewMessage",
            arrayOf(Long::class.java, Long::class.java, Long::class.java),
            Hook { hookParam ->
                val channelId = hookParam.args[0] as Long
                val guildId   = hookParam.args[1] as Long
                val messageId = hookParam.args[2] as Long

                if (!autoManager.isEnabled(channelId)) return@Hook
                if (autoManager.isPaused(channelId)) return@Hook

                // 异步读取消息并翻译
                Utils.threadPool.execute {
                    try {
                        val message = com.aliucord.wrappers.messages.Message(
                            com.discord.stores.StoreStream
                                .getMessages()
                                .getMessage(channelId, messageId)
                        )
                        val content = message.content ?: return@execute
                        if (content.isBlank()) return@execute

                        val targetLang = settings.getString(SETTINGS_KEY_DEFAULT_LANG, DEFAULT_TARGET_LANG)

                        // 语言检测：跳过目标语言的消息
                        if (!LanguageDetector.shouldTranslate(content, targetLang)) return@execute

                        val result = controller.translateSync(
                            text = content,
                            targetLang = targetLang,
                            channelId = channelId,
                            messageId = messageId
                        )

                        when (result) {
                            is TranslateResult.Success -> {
                                autoManager.recordSuccess(channelId)
                                Utils.mainThread { chatList?.let { list ->
                                    list.forceRerenderMessage(messageId)
                                }}
                            }
                            is TranslateResult.Error -> {
                                val justPaused = autoManager.recordFailure(channelId)
                                if (justPaused) {
                                    Utils.mainThread {
                                        Utils.showToast(strings.toastAutoPaused, true)
                                    }
                                }
                            }
                        }
                    } catch (_: Exception) { }
                }
            }
        )
    }

    private fun patchProcessMessageText() {
        val mDraweeStringBuilder: Field =
            SimpleDraweeSpanTextView::class.java.getDeclaredField("mDraweeStringBuilder")
        mDraweeStringBuilder.isAccessible = true

        patcher.patch(
            WidgetChatListAdapterItemMessage::class.java,
            "processMessageText",
            arrayOf(SimpleDraweeSpanTextView::class.java, MessageEntry::class.java),
            Hook {
                val messageEntry = it.args[1] as MessageEntry
                val message = messageEntry.message ?: return@Hook
                val id = message.id

                // 加载态：显示"翻译中..."
                if (controller.isLoading(id)) {
                    val textView = it.args[0] as SimpleDraweeSpanTextView
                    val builder = mDraweeStringBuilder[textView] as? DraweeSpanStringBuilder
                        ?: return@Hook
                    builder.replace(0, builder.length, strings.loadingText)
                    textView.setDraweeSpanStringBuilder(builder)
                    return@Hook
                }

                val data = controller.getCached(id) ?: return@Hook
                if (data.showingOriginal) return@Hook
                // 源文本内容变更检测（编辑过的消息不再翻译旧内容）
                if (data.sourceText != message.content) {
                    // 源文本变了，清除缓存（不直接 remove 避免 concurrent modification）
                    return@Hook
                }

                val textView = it.args[0] as SimpleDraweeSpanTextView
                val builder = mDraweeStringBuilder[textView] as? DraweeSpanStringBuilder
                    ?: return@Hook
                val ctx = textView.context

                applyTranslatedText(builder, data, ctx)
                textView.setDraweeSpanStringBuilder(builder)
            }
        )
    }

    private fun DraweeSpanStringBuilder.applyTranslatedText(
        data: TranslateResult.Success,
        ctx: Context
    ) {
        replace(0, length, data.translatedText)
        val textEnd = length
        val label = " (${strings.actionTranslate}: ${data.sourceLanguage} → ${data.translatedLanguage})"
        append(label)
        setSpan(RelativeSizeSpan(0.75f), textEnd, length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        setSpan(
            EditedMessageNode.Companion.`access$getForegroundColorSpan`(
                EditedMessageNode.Companion, ctx
            ),
            textEnd, length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
        )
    }

    private fun patchMessageContextMenu() {
        val viewId = View.generateViewId()
        val menuClass = WidgetChatListActions::class.java
        val getBinding = menuClass.getDeclaredMethod("getBinding").apply { isAccessible = true }

        // ── configureUI：注入翻译/显示原文按钮 ─────────────────────
        patcher.patch(
            menuClass.getDeclaredMethod("configureUI", WidgetChatListActions.Model::class.java),
            Hook { hookParam ->
                val menu = hookParam.thisObject as WidgetChatListActions
                val binding = getBinding.invoke(menu) as WidgetChatListActionsBinding
                val btn = binding.a.findViewById<TextView>(viewId) ?: return@Hook

                btn.setOnClickListener { view ->
                    val message = (hookParam.args[0] as WidgetChatListActions.Model).message
                    val cached = controller.getCached(message.id)

                    if (cached == null) {
                        // 翻译
                        controller.translateWithLoading(
                            text = message.content,
                            channelId = message.channelId,
                            messageId = message.id
                        )
                        Utils.mainThread { menu.dismiss() }
                    } else {
                        // 切换原文/译文
                        controller.toggleOriginal(message.id)
                        Utils.mainThread { menu.dismiss() }
                    }
                }
            }
        )

        // ── onViewCreated：在菜单末尾插入翻译按钮 ───────────────────
        patcher.patch(
            menuClass,
            "onViewCreated",
            arrayOf(View::class.java, Bundle::class.java),
            Hook { hookParam ->
                val scrollView = hookParam.args[0] as NestedScrollView
                val linearLayout = scrollView.getChildAt(0) as LinearLayout
                val ctx = linearLayout.context
                val messageId = WidgetChatListActions.`access$getMessageId$p`(
                    hookParam.thisObject as WidgetChatListActions
                )

                val cached = controller.getCached(messageId)
                val label = if (cached == null || cached.showingOriginal)
                    strings.actionTranslate else strings.actionShowOriginal

                linearLayout.addView(TextView(ctx, null, 0, R.i.UiKit_Settings_Item_Icon).apply {
                    id = viewId
                    text = label
                    setCompoundDrawablesRelativeWithIntrinsicBounds(pluginIcon, null, null, null)
                })

                // 如果该频道支持自动翻译，在菜单加一个切换按钮
                val channelId = WidgetChatListActions.`access$getChannelId$p`(
                    hookParam.thisObject as WidgetChatListActions
                )
                if (channelId != 0L) {
                    val autoLabel = if (autoManager.isEnabled(channelId))
                        strings.actionShowOriginal else strings.actionToggleAuto

                    linearLayout.addView(TextView(ctx, null, 0, R.i.UiKit_Settings_Item_Icon).apply {
                        text = autoLabel
                        setOnClickListener {
                            val nowOn = autoManager.toggle(channelId)
                            Utils.showToast(
                                if (nowOn) strings.toastAutoResumed else strings.toastAutoPaused
                            )
                            menu.dismiss()
                        }
                        setCompoundDrawablesRelativeWithIntrinsicBounds(pluginIcon, null, null, null)
                    })
                }
            }
        )
    }

    private fun registerTranslateCommand() {
        commands.registerCommand(
            CMD_NAME,
            "Translate text using the configured backend",
            listOf(
                Utils.createCommandOption(ApplicationCommandType.STRING, "text", "Text to translate"),
                Utils.createCommandOption(ApplicationCommandType.STRING, "to",
                    "Target language code (default: zh-CN)",
                    choices = languageCodeChoices),
                Utils.createCommandOption(ApplicationCommandType.STRING, "from",
                    "Source language code (default: auto)",
                    choices = languageCodeChoices),
                Utils.createCommandOption(ApplicationCommandType.BOOLEAN, "send",
                    "Send the translated text to chat? (default true)")
            )
        ) { ctx ->
            val result = controller.translateSync(
                text       = ctx.getRequiredString("text"),
                sourceLang = ctx.getString("from"),
                targetLang = ctx.getString("to")
            )
            return@registerCommand when (result) {
                is TranslateResult.Error ->
                    CommandsAPI.CommandResult(result.toString(), null, false)
                is TranslateResult.Success ->
                    CommandsAPI.CommandResult(
                        result.translatedText,
                        null,
                        ctx.getBoolOrDefault("send", true)
                    )
            }
        }
    }
}

package com.aliucord.plugins.translate

import com.aliucord.Utils
import com.aliucord.api.SettingsAPI
import com.aliucord.plugins.translate.backend.GoogleTranslator
import com.aliucord.plugins.translate.backend.LLMTranslator
import com.aliucord.plugins.translate.backend.TranslatorBackend
import com.aliucord.plugins.translate.utils.forceRerenderMessage
import com.discord.widgets.chat.list.WidgetChatList

/**
 * 翻译控制器：调度后端、管理结果缓存、驱动 UI 刷新。
 *
 * 职责：
 * 1. 根据用户设置选择后端（Google / LLM）
 * 2. 协调 TextCleaner 预处理
 * 3. 缓存译文结果
 * 4. 降级策略：LLM 失败自动回退 Google
 * 5. 通知 UI 刷新消息
 */
class TranslateController(
    private val settings: SettingsAPI,
    private val onShowToast: (String, Boolean) -> Unit = { msg, isLong -> Utils.showToast(msg, isLong) }
) {
    private val translatedMessages = mutableMapOf<Long, TranslateResult.Success>()
    private var chatList: WidgetChatList? = null

    fun attachChatList(list: WidgetChatList) { chatList = list }

    /**
     * 获取指定消息的缓存译文，若没有则返回 null。
     */
    fun getCached(messageId: Long): TranslateResult.Success? = translatedMessages[messageId]

    /**
     * 切换译文/原文显示。
     */
    fun toggleOriginal(messageId: Long) {
        translatedMessages[messageId]?.let {
            it.showingOriginal = !it.showingOriginal
            rerender(messageId)
        }
    }

    /**
     * 判断消息是否已翻译且当前显示译文。
     */
    fun isShowingTranslation(messageId: Long): Boolean =
        translatedMessages[messageId]?.showingOriginal == false

    /**
     * 同步翻译（调用前请已在后台线程）。
     * 返回 Success 或 Error。
     */
    fun translateSync(
        text: String,
        sourceLang: String? = null,
        targetLang: String? = null,
        channelId: Long? = null,
        messageId: Long? = null
    ): TranslateResult {
        val cleanedText = TextCleaner.clean(text, settings)
        val target = targetLang ?: settings.getString(SETTINGS_KEY_DEFAULT_LANG, DEFAULT_TARGET_LANG)

        val backend = resolveBackend()
        var result = backend.translate(cleanedText, sourceLang, target)

        // LLM 失败降级到 Google
        if (result is TranslateResult.Error && backend !is GoogleTranslator) {
            val fallback = GoogleTranslator()
            val fbResult = fallback.translate(cleanedText, sourceLang, target)
            if (fbResult is TranslateResult.Success) {
                result = fbResult
                Utils.mainThread {
                    onShowToast("已降级到 Google Translate", false)
                }
            }
        }

        // 成功时缓存
        if (result is TranslateResult.Success && messageId != null) {
            translatedMessages[messageId] = result
        }

        return result
    }

    /**
     * 异步翻译：在后台线程执行，完成后在主线程刷新 UI。
     */
    fun translateAsync(
        text: String,
        sourceLang: String? = null,
        targetLang: String? = null,
        channelId: Long? = null,
        messageId: Long,
        onComplete: ((TranslateResult) -> Unit)? = null
    ) {
        Utils.threadPool.execute {
            val result = translateSync(text, sourceLang, targetLang, channelId, messageId)
            Utils.mainThread {
                if (result is TranslateResult.Success) {
                    rerender(messageId)
                }
                onComplete?.invoke(result)
            }
        }
    }

    /**
     * 翻译并在缓存命中时显示"翻译中…"占位。
     */
    fun translateWithLoading(
        text: String,
        sourceLang: String? = null,
        targetLang: String? = null,
        channelId: Long? = null,
        messageId: Long
    ) {
        // 先存一个占位符，让 processMessageText 渲染"翻译中…"
        translatedMessages[messageId] = TranslateResult.Success(
            sourceLanguage = "",
            translatedLanguage = "",
            sourceText = text,
            translatedText = "",
            showingOriginal = false
        )
        rerender(messageId)

        translateAsync(text, sourceLang, targetLang, channelId, messageId)
    }

    fun isLoading(messageId: Long): Boolean =
        translatedMessages[messageId]?.let {
            it.translatedText.isEmpty() && !it.showingOriginal
        } ?: false

    private fun resolveBackend(): TranslatorBackend {
        val choice = settings.getString(SETTINGS_KEY_BACKEND, "google")
        return if (choice == "llm") {
            LLMTranslator(
                baseUrl  = settings.getString(SETTINGS_KEY_LLM_BASE_URL, ""),
                apiKey   = settings.getString(SETTINGS_KEY_LLM_API_KEY, ""),
                model    = settings.getString(SETTINGS_KEY_LLM_MODEL, "gpt-4o-mini"),
                systemPrompt = settings.getString(
                    SETTINGS_KEY_LLM_SYSTEM_PROMPT,
                    LLMTranslator.DEFAULT_SYSTEM_PROMPT
                )
            )
        } else {
            GoogleTranslator()
        }
    }

    private fun rerender(messageId: Long) {
        chatList?.let { list ->
            Utils.mainThread { list.forceRerenderMessage(messageId) }
        }
    }
}

package com.aliucord.plugins.translate

sealed class TranslateResult {
    data class Success(
        val sourceLanguage: String,
        val translatedLanguage: String,
        val sourceText: String,
        val translatedText: String,
        var showingOriginal: Boolean = false
    ) : TranslateResult()

    data class Error(
        val errorCode: Int? = null,
        val errorText: String
    ) : TranslateResult() {
        override fun toString(): String =
            if (errorCode != null) "$errorText ($errorCode)" else errorText
    }
}

package com.aliucord.plugins.translate.auto

import com.aliucord.api.SettingsAPI

/**
 * 管理自动翻译的状态：按频道开关、失败计数、暂停逻辑。
 *
 * 频道开关状态持久化在 SettingsAPI 中，key 格式：
 *   autoTranslate_enabled_{channelId}  -> Boolean
 *
 * 运行时失败计数在内存中，不持久化。
 */
class AutoTranslateManager(private val settings: SettingsAPI) {

    private val failCounts = mutableMapOf<Long, Int>()
    private val pausedChannels = mutableSetOf<Long>()

    /**
     * 用户是否对该频道开启了自动翻译。
     */
    fun isEnabled(channelId: Long): Boolean =
        settings.getBool("autoTranslate_enabled_$channelId", false)

    /**
     * 切换某个频道的自动翻译开关。
     */
    fun toggle(channelId: Long): Boolean {
        val now = !isEnabled(channelId)
        settings.setBool("autoTranslate_enabled_$channelId", now)
        if (now) {
            pausedChannels.remove(channelId)
            failCounts.remove(channelId)
        }
        return now
    }

    /**
     * 是否因连续失败而暂停。
     */
    fun isPaused(channelId: Long): Boolean = channelId in pausedChannels

    /**
     * 记录一次翻译失败，返回该频道是否刚被暂停。
     */
    fun recordFailure(channelId: Long, maxFailures: Int = MAX_FAILURES): Boolean {
        if (channelId in pausedChannels) return true
        val count = (failCounts[channelId] ?: 0) + 1
        failCounts[channelId] = count
        if (count >= maxFailures) {
            pausedChannels.add(channelId)
            return true
        }
        return false
    }

    /**
     * 记录一次翻译成功，重置失败计数。
     */
    fun recordSuccess(channelId: Long) {
        failCounts.remove(channelId)
    }

    /**
     * 手动恢复被暂停的频道。
     */
    fun resume(channelId: Long) {
        pausedChannels.remove(channelId)
        failCounts[channelId] = 0
    }

    companion object {
        private const val MAX_FAILURES = 3
    }
}

package com.aliucord.plugins.translate.backend

import com.aliucord.Http
import com.aliucord.plugins.translate.GOOGLE_TRANSLATE_API_URL
import com.aliucord.plugins.translate.TranslateResult
import com.aliucord.plugins.translate.USER_AGENT
import com.aliucord.plugins.translate.utils.TranslateUnescaper
import org.json.JSONArray

class GoogleTranslator : TranslatorBackend {

    override fun translate(
        text: String,
        sourceLang: String?,
        targetLang: String
    ): TranslateResult {
        val from = sourceLang?.ifEmpty { "auto" } ?: "auto"
        val url = Http.QueryBuilder(GOOGLE_TRANSLATE_API_URL).apply {
            append("client", "gtx")
            append("sl", from)
            append("tl", targetLang)
            append("dt", "t")
            append("q", text)
        }.toString()

        val response = Http.Request(url, "GET").apply {
            setHeader("Content-Type", "application/json")
            setHeader("User-Agent", USER_AGENT)
        }.execute()

        if (!response.ok()) {
            return TranslateResult.Error(
                errorCode = response.statusCode,
                errorText = when (response.statusCode) {
                    429 -> "Google Translate rate limited. Try again later."
                    else -> "Google Translate request failed."
                }
            )
        }

        val json   = JSONArray(response.text())
        val parts  = json.getJSONArray(0)
        val translated = buildString {
            for (i in 0 until parts.length()) {
                append(parts.getJSONArray(i).getString(0))
            }
        }.let { TranslateUnescaper.unescape(it) }

        return TranslateResult.Success(
            sourceLanguage    = json.optString(2, from),
            translatedLanguage = targetLang,
            sourceText        = text,
            translatedText    = translated
        )
    }
}

package com.aliucord.plugins.translate.backend

import com.aliucord.Http
import com.aliucord.plugins.translate.TranslateResult
import com.aliucord.plugins.translate.USER_AGENT
import org.json.JSONArray
import org.json.JSONObject

class LLMTranslator(
    private val baseUrl: String,
    private val apiKey: String,
    private val model: String,
    private val systemPrompt: String = DEFAULT_SYSTEM_PROMPT
) : TranslatorBackend {

    override fun translate(
        text: String,
        sourceLang: String?,
        targetLang: String
    ): TranslateResult {
        if (apiKey.isBlank() || baseUrl.isBlank()) {
            return TranslateResult.Error(
                errorText = "LLM API key or base URL not configured."
            )
        }

        val userPrompt = buildUserPrompt(text, sourceLang, targetLang)

        val requestBody = JSONObject().apply {
            put("model", model)
            put("temperature", 0.0)
            put("max_tokens", 2048)
            put("messages", JSONArray().apply {
                put(JSONObject().apply {
                    put("role", "system")
                    put("content", systemPrompt)
                })
                put(JSONObject().apply {
                    put("role", "user")
                    put("content", userPrompt)
                })
            })
        }

        val url = baseUrl.trimEnd('/') + "/v1/chat/completions"

        return try {
            val response = Http.Request(url, "POST").apply {
                setHeader("Content-Type", "application/json")
                setHeader("Authorization", "Bearer $apiKey")
                setHeader("User-Agent", USER_AGENT)
                setBody(requestBody.toString())
            }.execute()

            if (!response.ok()) {
                return TranslateResult.Error(
                    errorCode = response.statusCode,
                    errorText = "LLM API request failed: ${response.text().take(200)}"
                )
            }

            val json  = JSONObject(response.text())
            val content = json.getJSONArray("choices")
                .getJSONObject(0)
                .getJSONObject("message")
                .getString("content")
                .trim()

            TranslateResult.Success(
                sourceLanguage    = sourceLang ?: "auto",
                translatedLanguage = targetLang,
                sourceText        = text,
                translatedText    = content
            )
        } catch (e: Exception) {
            TranslateResult.Error(errorText = "LLM request exception: ${e.message}")
        }
    }

    private fun buildUserPrompt(text: String, sourceLang: String?, targetLang: String): String {
        val langPart = if (sourceLang != null && sourceLang != "auto")
            "from $sourceLang " else ""
        return "Translate ${langPart}to $targetLang. " +
            "Only return the translated text, nothing else.\n\n$text"
    }

    companion object {
        const val DEFAULT_SYSTEM_PROMPT =
            "You are a professional translator. " +
            "Only output the translated text, no explanations."
    }
}

package com.aliucord.plugins.translate.utils

import java.io.StringWriter
import java.io.Writer

object TranslateUnescaper {

    fun unescape(input: String): String {
        val writer = StringWriter(input.length * 2)
        var pos = 0
        val len = input.length

        while (pos < len) {
            val consumed = translate(input, pos, writer)
            if (consumed == 0) {
                val c1 = input[pos]
                writer.write(c1.code)
                pos++
                if (Character.isHighSurrogate(c1) && pos < len) {
                    val c2 = input[pos]
                    if (Character.isLowSurrogate(c2)) {
                        writer.write(c2.code)
                        pos++
                    }
                }
                continue
            }
            for (pt in 0 until consumed) {
                pos += Character.charCount(Character.codePointAt(input, pos))
            }
        }
        return writer.toString()
    }

    private fun translate(input: String, index: Int, writer: Writer): Int {
        if (input[index] == '\\' && index + 1 < input.length && input[index + 1] == 'u') {
            var i = 2
            while (index + i < input.length && input[index + i] == 'u') i++
            if (index + i < input.length && input[index + i] == '+') i++

            if (index + i + 4 <= input.length) {
                val hex = input.subSequence(index + i, index + i + 4)
                try {
                    writer.write(hex.toString().toInt(16).toChar().code)
                } catch (_: NumberFormatException) { }
                return i + 4
            }
        }
        return 0
    }
}

package com.aliucord.plugins.translate.utils

import com.aliucord.CollectionUtils
import com.discord.widgets.chat.list.WidgetChatList
import com.discord.widgets.chat.list.entries.MessageEntry

/**
 * 自实现的 rerenderMessage，直接操作 adapter，不依赖 Aliucord 内部 API。
 * 用于翻译完成后强制刷新单条消息视图。
 */
fun WidgetChatList.forceRerenderMessage(messageId: Long) {
    try {
        val adapter = WidgetChatList.`access$getAdapter$p`(this)
        val data = adapter.internalData
        val idx = CollectionUtils.findIndex(data) { entry ->
            entry is MessageEntry && entry.message.id == messageId
        }
        if (idx != -1) adapter.notifyItemChanged(idx)
    } catch (_: Exception) {
        // 如果内部 API 变动，静默忽略，不影响主流程
    }
}
